mapper.select:
SELECT id, tool_id, tenant_id, role_id, decision, priority, enabled
FROM tool_permission
WHERE tool_id = #{toolId}
  AND tenant_id = #{tenantId}
  AND role_id = #{roleId}
LIMIT 1

mapper.update:
UPDATE tool_permission
SET enabled = 0
WHERE tool_id = #{toolId}
  AND tenant_id = #{tenantId}
  AND role_id = #{roleId}
  AND enabled = 1

UPDATE tool_permission
SET enabled = 1
WHERE tool_id = #{toolId}
  AND tenant_id = #{tenantId}
  AND role_id = #{roleId}
  AND enabled = 0

UPDATE tool_permission
SET priority = #{priority}
WHERE tool_id = #{toolId}
  AND tenant_id = #{tenantId}
  AND role_id = #{roleId}
